/* getUserAuthExists - Lee JiSeob */

SELECT
    MENU_NO
FROM SAB250
WHERE USER_ID = #{userId} 
AND MENU_NO IN



    #{item}

SELECT /* SQL-ID : isry.itgcms.sysmgmt.userauth.mapper.MgmtUserAuthMapper.selectUserAuthList : 사용자별 메뉴 권한 목록 조회 */ A.USER_ID /* 사용자아이디 */ , A.MENU_NO /* 메뉴번호 */ , A.INQ_BUTTON_USE_YN /* 조회버튼사용여부 */ , A.INITL_BUTTON_USE_YN /* 초기화버튼사용여부 */ , A.REG_BUTTON_USE_YN /* 등록버튼사용여부 */ , A.MDFCN_BUTTON_USE_YN /* 수정버튼사용여부 */ , A.DEL_BUTTON_USE_YN /* 삭제버튼사용여부 */ , A.MNG_BUTTON_USE_YN /* 관리버튼사용여부 */ , A.DTL_INQ_BUTTON_USE_YN /* 상세조회버튼사용여부 */ , A.FRST_RGTR_ID /* 최초등록자아이디 */ , A.FRST_REG_DT /* 최초등록일시 */ , A.LAST_MDFR_ID /* 최종수정자아이디 */ , A.LAST_MDFCN_DT /* 최종수정일시 */ FROM SAB250 A /** 사용자별 메뉴권한 */ WHERE 1=1 AND A.USER_ID = #{USER_ID} /* 사용자아이디 */ AND A.MENU_NO IN ( SELECT MENU_NO /* 메뉴번호 */ FROM ( SELECT AM.MENU_NO /* 메뉴번호 */ , ROW_NUMBER() OVER(PARTITION BY AM.MENU_NO ORDER BY AM.MENU_NO ASC) AS ROW_NUM FROM SAB300 AM /** 권한별 메뉴 */ , SAB400 AU /** 권한 */ WHERE 1=1 AND AM.AUTHRT_ID IN /* 권한아이디 (복수) */
#{authrtId}
AND AU.AUTHRT_ID = AM.AUTHRT_ID AND AU.DEL_YN = 'N' ORDER BY AM.MENU_NO ASC ) T WHERE ROW_NUM = 1 /* 메뉴번호 중복제거 */ )
AND A.MENU_NO NOT IN /* 제외할 메뉴번호 */
#{menuNo}

mapper.delete:

/* deleteUserAuth - Lee JiSeob */

DELETE FROM SAB250
WHERE USER_ID = #{userId} 
AND MENU_NO = #{menuId}


/* deleteUnavailUserAuth - Lee JiSeob */

DELETE FROM SAB250 C
WHERE NOT EXISTS (
    SELECT D.MENU_NO FROM SAB200 D WHERE D.MENU_NO = C.MENU_NO
)

/* SQL-ID : isry.itgcms.sysmgmt.userauth.mapper.MgmtUserAuthMapper.deleteUserAuthByAuthrtIds : 사용자별 메뉴권한 일괄 삭제 (권한아이디 기준) */ DELETE FROM SAB250 /** 사용자별 메뉴권한 */ WHERE USER_ID = #{USER_ID} /* 사용자아이디 */ AND MENU_NO IN ( SELECT MENU_NO FROM ( SELECT AM.MENU_NO /* 메뉴번호 */ , ROW_NUMBER() OVER(PARTITION BY AM.MENU_NO ORDER BY AM.MENU_NO ASC) AS ROW_NUM FROM SAB300 AM /** 권한별 메뉴 */ WHERE 1=1
AND AM.AUTHRT_ID IN /* 권한아이디 (복수) */
#{authrtId}
ORDER BY AM.MENU_NO ASC ) T WHERE ROW_NUM = 1 /* 메뉴번호 중복제거 */ )
AND MENU_NO NOT IN /* 삭제 제외할 메뉴번호 */
#{menuNo}


   /* deleteUserAuthWithId - Lee JiSeob */

   DELETE FROM SAB250
   WHERE USER_ID = #{userId}


   AND MENU_NO NOT IN          /* 삭제 제외할 메뉴번호 */

#{menuNo}
